import { SchemaExtensions } from './SchemaExtensions';
import { internalNameFor, SchemaArtifactKind } from './AbstractSchemaArtifact';
import { CedarArtifactType } from './types/cedar-types/CedarArtifactType';
import { IsoDate } from './types/wrapped-types/IsoDate';
import { CedarUser } from './types/cedar-types/CedarUser';
import { PavVersion } from './types/wrapped-types/PavVersion';
import { BiboStatus } from './types/wrapped-types/BiboStatus';
import { CedarArtifactId } from './types/cedar-types/CedarArtifactId';
import { SchemaVersion } from './types/wrapped-types/SchemaVersion';
import { AbstractSchemaArtifact } from './AbstractSchemaArtifact';
import { JavaStrings } from './util/JavaStrings';

export abstract class AbstractArtifactBuilder {
  protected at_id: CedarArtifactId = CedarArtifactId.NULL;
  protected title: string | null = null;
  protected description: string | null = null;
  protected schema_schemaVersion: SchemaVersion = SchemaVersion.CURRENT;
  // provenance
  protected pav_createdOn: IsoDate = IsoDate.NULL;
  protected pav_createdBy: CedarUser = CedarUser.NULL;
  protected pav_lastUpdatedOn: IsoDate = IsoDate.NULL;
  protected oslc_modifiedBy: CedarUser = CedarUser.NULL;
  // status and version
  protected extensions: SchemaExtensions = new SchemaExtensions();

  public withExtensions(extensions: SchemaExtensions): this {
    this.extensions = extensions;
    return this;
  }

  protected pav_version: PavVersion = PavVersion.DEFAULT;
  protected bibo_status: BiboStatus = BiboStatus.DRAFT;
  // schema name and description
  protected schema_name: string | null = null;
  protected schema_description: string = '';
  protected schema_identifier: string | null = null;
  //
  protected pav_derivedFrom: CedarArtifactId = CedarArtifactId.NULL;

  withAtId(at_id: CedarArtifactId | string): this {
    if (at_id instanceof CedarArtifactId) {
      this.at_id = at_id;
    } else {
      this.at_id = CedarArtifactId.forValue(at_id);
    }
    return this;
  }

  withTitle(title: string | null): this {
    this.title = title;
    return this;
  }

  withDescription(description: string | null): this {
    this.description = description;
    return this;
  }

  withSchemaVersion(schema_schemaVersion: SchemaVersion): this {
    this.schema_schemaVersion = schema_schemaVersion;
    return this;
  }

  withCreatedOn(createdOn: IsoDate | string | null): this {
    if (createdOn instanceof IsoDate) {
      this.pav_createdOn = createdOn;
    } else {
      this.pav_createdOn = IsoDate.forValue(createdOn);
    }
    return this;
  }

  withCreatedBy(createdBy: CedarUser | string): this {
    if (createdBy instanceof CedarUser) {
      this.pav_createdBy = createdBy;
    } else {
      this.pav_createdBy = CedarUser.forValue(createdBy);
    }
    return this;
  }

  withLastUpdatedOn(lastUpdatedOn: IsoDate | string | null): this {
    if (lastUpdatedOn instanceof IsoDate) {
      this.pav_lastUpdatedOn = lastUpdatedOn;
    } else {
      this.pav_lastUpdatedOn = IsoDate.forValue(lastUpdatedOn);
    }
    return this;
  }

  withModifiedBy(modifiedBy: CedarUser | string): this {
    if (modifiedBy instanceof CedarUser) {
      this.oslc_modifiedBy = modifiedBy;
    } else {
      this.oslc_modifiedBy = CedarUser.forValue(modifiedBy);
    }
    return this;
  }

  withVersion(version: PavVersion | string): this {
    if (version instanceof PavVersion) {
      this.pav_version = version;
    } else {
      this.pav_version = PavVersion.forValue(version);
    }
    return this;
  }

  withStatus(bibo_status: BiboStatus | string): this {
    if (bibo_status instanceof BiboStatus) {
      this.bibo_status = bibo_status;
    } else {
      this.bibo_status = BiboStatus.forJsonValue(bibo_status);
    }
    return this;
  }

  withSchemaName(schema_name: string | null): this {
    this.schema_name = schema_name;
    return this;
  }

  withSchemaDescription(schema_description: string | null): this {
    // Null and absent both mean no description, and the model spells that as an empty string.
    this.schema_description = schema_description ?? '';
    return this;
  }

  withDerivedFrom(pav_derivedFrom: CedarArtifactId): this {
    this.pav_derivedFrom = pav_derivedFrom;
    return this;
  }

  public withSchemaIdentifier(schema_identifier: string): this {
    this.schema_identifier = schema_identifier;
    return this;
  }

  protected buildInternal(artifact: AbstractSchemaArtifact): void {
    this.assertNameNotBlank(artifact.cedarArtifactType);
    artifact.at_id = this.at_id;
    artifact.title = this.title;
    artifact.description = this.description;
    artifact.schema_schemaVersion = this.schema_schemaVersion;

    artifact.pav_createdOn = this.pav_createdOn;
    artifact.pav_createdBy = this.pav_createdBy;
    artifact.pav_lastUpdatedOn = this.pav_lastUpdatedOn;
    artifact.oslc_modifiedBy = this.oslc_modifiedBy;

    artifact.extensions = this.extensions;
    artifact.pav_version = this.pav_version;
    artifact.bibo_status = this.bibo_status;

    artifact.schema_name = this.schema_name;
    artifact.schema_description = this.schema_description;
    artifact.schema_identifier = this.schema_identifier;

    artifact.pav_derivedFrom = this.pav_derivedFrom;

    // A title is composed from the name, so an artifact built without one still carries the title
    // a reader derives. Without this, writing a built artifact emitted a null title - which the
    // meta-schema refuses, since it asks for a non-empty string - and writing, reading and writing
    // again gave two different documents. A title someone set explicitly is left as they set it.
    if (artifact.title === null && artifact.schema_name !== null) {
      const kind = AbstractArtifactBuilder.kindOf(artifact.cedarArtifactType);
      if (kind !== null) {
        artifact.title = internalNameFor(artifact.schema_name, kind);
      }
    }
  }

  /**
   * Refuse a template, element or field name that is not empty but is made only of whitespace, as the
   * Java library's builders refuse it. Whitespace is what Java's `String.isBlank` counts: the ASCII
   * controls from tab to carriage return and from U+001C to U+001F, the space, and the Unicode space,
   * line and paragraph separators other than the no-break spaces. An empty or absent name is not
   * refused here. Every template, element and field builder reaches this check when it builds, and
   * nothing else does. The readers construct artifacts without a builder, so they accept such a name,
   * as the meta-schema does.
   */
  private assertNameNotBlank(type: CedarArtifactType): void {
    const name = this.schema_name;
    if (name === null || name === '' || !JavaStrings.isBlank(name)) {
      return;
    }
    const kind = AbstractArtifactBuilder.kindOf(type) ?? 'artifact';
    const article = kind === 'element' || kind === 'artifact' ? 'an' : 'a';
    throw new Error(`The name ${JSON.stringify(name)} is made only of whitespace, so ${article} ${kind} cannot be built with it.`);
  }

  private static kindOf(type: CedarArtifactType): SchemaArtifactKind | null {
    if (type === CedarArtifactType.TEMPLATE) return 'template';
    if (type === CedarArtifactType.TEMPLATE_ELEMENT) return 'element';
    if (type === CedarArtifactType.TEMPLATE_FIELD || type === CedarArtifactType.STATIC_TEMPLATE_FIELD) return 'field';
    return null;
  }
}
