import { ExactDecimal, NumericPolicy, NumericValue } from '../../policy/NumericPolicy';
import { IdentifierPolicy } from '../../policy/IdentifierPolicy';
import { JsonNode } from '../../model/cedar/types/basic-types/JsonNode';
import { Iri } from '../../model/cedar/types/wrapped-types/Iri';
import { NullableNumber } from '../../model/cedar/types/basic-types/NullableNumber';
import { JsonPath } from '../../model/cedar/util/path/JsonPath';
import { JsonSourcePolicy } from '../../policy/JsonSourcePolicy';

export abstract class ReaderUtil {
  public static assertIdentifierCharacters = IdentifierPolicy.assertIdentifierCharacters.bind(IdentifierPolicy);
  public static assertFieldIri = IdentifierPolicy.assertFieldIri.bind(IdentifierPolicy);
  public static assertIri = IdentifierPolicy.assertIri.bind(IdentifierPolicy);
  public static assertIdentifier = IdentifierPolicy.assertIdentifier.bind(IdentifierPolicy);

  /** The string at `key`, held to `assertIri`. */
  public static getIri(node: JsonNode, key: string): string | null {
    const raw = this.getString(node, key);
    this.assertIri(raw, key);
    return raw;
  }

  /** The string at `key`, held to `assertIdentifier`. */
  public static getIdentifier(node: JsonNode, key: string): string | null {
    const raw = this.getString(node, key);
    this.assertIdentifier(raw, key);
    return raw;
  }

  /**
   * An artifact's identifier as a reader's behavior holds it. A strict reader holds the Java rule,
   * `assertIdentifier`. A compatibility reader takes what it always has, `assertIri`: older documents
   * carry relative references here, such as a draft's placeholder, and an empty string where there
   * was none, which `CedarArtifactId` makes absence of so the writer omits the key. The server
   * refuses either on a write.
   */
  public static getArtifactIdentifier(node: JsonNode, key: string, lenient: boolean): string | null {
    if (lenient) return this.getIri(node, key);
    return this.getIdentifier(node, key);
  }

  public static getString(node: JsonNode, key: string): string | null {
    if (Object.hasOwn(node, key)) {
      return node[key] as string;
    } else {
      return null;
    }
  }

  /**
   * A field value's `@type`, which is at most one IRI.
   *
   * A lone IRI may arrive as a string or as a one-element list, and an empty list means none, as in
   * Java's reader. A longer list is refused: the model has one slot for it, and keeping the first
   * entry would discard the rest.
   */
  public static getSingleType(node: JsonNode, key: string): string | null {
    if (!Object.hasOwn(node, key)) {
      return null;
    }
    const type: unknown = node[key];
    if (!Array.isArray(type)) {
      return type as string | null;
    }
    if (type.length > 1) {
      throw new Error(`A field value can have at most one ${key}.`);
    }
    return type.length === 1 ? (type[0] as string) : null;
  }

  public static getStringOrEmpty(node: JsonNode, key: string): string {
    if (Object.hasOwn(node, key)) {
      return node[key] as string;
    } else {
      return '';
    }
  }

  public static getBoolean(node: JsonNode, key: string): boolean {
    if (Object.hasOwn(node, key)) {
      return node[key] as boolean;
    } else {
      return false;
    }
  }

  public static getBooleanOrNullOrUndefined(node: JsonNode, key: string): boolean | null | undefined {
    if (Object.hasOwn(node, key)) {
      if (node[key] === null) {
        return null;
      } else {
        return node[key] as boolean;
      }
    } else {
      return undefined;
    }
  }

  public static getBooleanOrNull(node: JsonNode, key: string): boolean | null {
    if (Object.hasOwn(node, key)) {
      if (node[key] === null) {
        return null;
      } else {
        return node[key] as boolean;
      }
    } else {
      return null;
    }
  }

  static getNumber(node: JsonNode, key: string): NullableNumber {
    if (Object.hasOwn(node, key)) {
      return node[key] as number;
    } else {
      return null;
    }
  }

  /**
   * Read a numeric default from either of CEDAR's supported encodings.
   *
   * JSON writes numeric defaults as strings to satisfy the CEDAR field schema,
   * while YAML normally uses a numeric scalar. Older JSON documents may also
   * contain a bare number, so readers accept both and retain an exact numeric value.
   */
  public static getNumericDefault(node: JsonNode, key: string): NumericValue | null {
    const raw = node[key];
    if (raw === null || raw === undefined || raw === '') return null;
    if (typeof raw === 'number' || typeof raw === 'string' || ExactDecimal.isExact(raw)) {
      try {
        return NumericPolicy.value(raw);
      } catch (cause) {
        throw new Error('Numeric default must be a finite decimal number without surrounding whitespace.', { cause });
      }
    }
    throw new Error(`Numeric default at "${key}" must be a number or numeric string.`);
  }

  public static getExactNumber(node: JsonNode, key: string): NumericValue | null {
    const raw = node[key];
    if (raw === null || raw === undefined) return null;
    if (typeof raw === 'number' || ExactDecimal.isExact(raw)) return NumericPolicy.value(raw);
    throw new Error(`Numeric bound at "${key}" must be a JSON number.`);
  }

  /**
   * The integer at `key`, or null where the node states none or states null, as Java's readers hold an
   * optional Java `int`. `spelling` is how the source wrote the value, where that is known. Any other
   * value is judged as `javaInt` judges it.
   */
  static getJavaIntOrNull(node: JsonNode, key: string, path: JsonPath, spelling: { text: string; integer: boolean } | null): number | null {
    const value: unknown = Object.hasOwn(node, key) ? node[key] : undefined;
    return value === undefined || value === null ? null : this.javaInt(value, key, path, spelling);
  }

  /** `getJavaIntOrNull` for a node parsed from JSON text, where a number written as a decimal is not an integer. */
  static getJsonJavaIntOrNull(node: JsonNode, key: string, path: JsonPath): number | null {
    return this.getJavaIntOrNull(node, key, path, this.jsonSpelling(node, key));
  }

  /**
   * The integer at `key` in a node parsed from JSON text, as Java's `readRequiredInt` reads one. The
   * node must state it, so an absent key is refused with an error that names the key and the path. A
   * stated null is refused, and any other value is judged as `javaInt` judges it.
   */
  static getRequiredJsonJavaInt(node: JsonNode, key: string, path: JsonPath): number {
    const value: unknown = Object.hasOwn(node, key) ? node[key] : undefined;
    if (value === undefined) {
      throw new Error(`Missing ${key} at ${path.add(key).toPointer()}. Expected an integer from -2147483648 to 2147483647.`);
    }
    return this.javaInt(value, key, path, this.jsonSpelling(node, key));
  }

  /**
   * `value`, the value stated at `key`, as a Java `int`: a number the source typed as an integer, from
   * -2147483648 to 2147483647. `spelling` is how the source wrote the value, where that is known, and
   * says whether the source typed it as an integer. A value of no known spelling is judged by its value
   * alone. Any other value is refused with an error that names the key and the path. A null, a
   * fraction, a number written as a decimal, a number past that range, a string, a boolean, a list and a
   * mapping are all refused.
   */
  private static javaInt(value: unknown, key: string, path: JsonPath, spelling: { text: string; integer: boolean } | null): number {
    if (
      typeof value === 'number' &&
      Number.isInteger(value) &&
      value >= -2147483648 &&
      value <= 2147483647 &&
      spelling?.integer !== false
    ) {
      // Java reads `-0` as the integer 0.
      return value === 0 ? 0 : value;
    }
    const shown = spelling?.text ?? JsonSourcePolicy.stringify(value);
    throw new Error(`Invalid ${key} ${shown} at ${path.add(key).toPointer()}. Expected an integer from -2147483648 to 2147483647.`);
  }

  /** How JSON text spelled the number at `key`, where it wrote one as a decimal, which no Java `int` reads. */
  private static jsonSpelling(node: JsonNode, key: string): { text: string; integer: boolean } | null {
    const decimal = JsonSourcePolicy.decimalSpelling(node, key);
    return decimal === null ? null : { text: decimal, integer: false };
  }

  public static getNode(node: JsonNode, key: string): JsonNode {
    if (Object.hasOwn(node, key)) {
      return node[key] as JsonNode;
    } else {
      return JsonNode.getEmpty();
    }
  }

  public static getNodeOrNull(node: JsonNode, key: string): JsonNode | null {
    if (Object.hasOwn(node, key)) {
      return node[key] as JsonNode;
    } else {
      return null;
    }
  }

  public static getStringList(node: JsonNode, key: string): Array<string> {
    if (Object.hasOwn(node, key) && Array.isArray(node[key])) {
      return node[key] as Array<string>;
    } else {
      return [];
    }
  }

  public static getFilteredStringList(node: JsonNode, key: string): Array<string> {
    if (Object.hasOwn(node, key) && Array.isArray(node[key])) {
      return (node[key] as Array<string>).filter((str) => str !== '');
    } else {
      return [];
    }
  }

  static getStringMap(node: JsonNode, key: string): Map<string, string> {
    if (Object.hasOwn(node, key) && typeof node[key] === 'object' && !Array.isArray(node[key]) && node[key] !== null) {
      const obj = node[key] as JsonNode;
      const entries: [string, string][] = Object.entries(obj as Record<string, string>);
      const map: Map<string, string> = new Map<string, string>();
      for (const [k, v] of entries) {
        map.set(k, v);
      }
      return map;
    } else {
      return new Map();
    }
  }

  public static deepClone(obj: object) {
    //return JSON.parse(JSON.stringify(obj));
    return this.deepUnfreeze(obj);
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  public static deepUnfreeze(object: any): any {
    if (object instanceof ExactDecimal) return object;
    if (object === null || (typeof object !== 'object' && typeof object !== 'function')) {
      return object;
    }

    // Create a shallow clone for array or object
    const clone = Array.isArray(object) ? object.slice() : { ...object };

    Object.getOwnPropertyNames(clone).forEach((prop) => {
      clone[prop] = this.deepUnfreeze(clone[prop]);
    });

    return clone;
  }

  public static deepFreeze<T extends object>(object: T): T {
    Object.freeze(object);
    Object.getOwnPropertyNames(object).forEach((prop) => {
      const propValue = object[prop as keyof T];
      if (propValue !== null && (typeof propValue === 'object' || typeof propValue === 'function') && !Object.isFrozen(propValue)) {
        this.deepFreeze(propValue as T);
      }
    });
    return object;
  }

  public static getNodeList(node: JsonNode, key: string): Array<JsonNode> {
    if (Object.hasOwn(node, key) && Array.isArray(node[key])) {
      return node[key] as Array<JsonNode>;
    } else {
      return JsonNode.getEmptyList();
    }
  }

  static getURI(node: JsonNode, key: string): Iri {
    const raw = this.getStringOrEmpty(node, key);
    this.assertIri(raw, key);
    return new Iri(raw);
  }

  /** A required identifier: absent, null and the empty string are refused alike, as Java refuses them. */
  static getIdentifierURI(node: JsonNode, key: string): Iri {
    const raw = this.getStringOrEmpty(node, key);
    this.assertIdentifier(raw === null ? '' : raw, key);
    return new Iri(raw);
  }

  static deleteNodeKey(node: JsonNode, key: string) {
    if (Object.hasOwn(node, key)) {
      delete node[key];
    }
  }
}
